def encode(message):
    vowels = {'a', 'e', 'i', 'o', 'u'}
    result = []

    for char in message:
        if char.isalpha():
            if char in vowels:
                # Replace vowel with the letter 2 places ahead
                vowel_index = vowels.index(char)
                new_vowel = chr(ord(vowels[vowel_index]) + 2)
                result.append(new_vowel)
            else:
                # Swap case
                result.append(char.swapcase())
        else:
            # Leave non-letters unchanged
            result.append(char)

    return ''.join(result)

