def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            if i > 0 and text[i-1] == ' ':
                # Replace consecutive spaces with -
                if i < len(text) - 1 and text[i+1] == ' ':
                    result.append('-')
                    i += 2
                else:
                    result.append('_')
                    i += 1
            else:
                result.append('_')
                i += 1
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

